"#!/usr/bin/env python3
"""
Create an OpenFOAM 10 buoyantFoam case for a 3D Rayleigh-Bénard cell.

Domain : 9 m (x) x 1 m (y) x 2 m (z)
Hot wall (y=0): 310 K
Cold wall (y=1): 300 K
Time : 0 -> 1000 s, dt = 1 s, write every 50 s.
"""

import os

CASE_DIR = os.getcwd()


def write_file(path, content):
    full = os.path.join(CASE_DIR, path)
    os.makedirs(os.path.dirname(full), exist_ok=True)
    with open(full, "w") as f:
        f.write(content)


# --------------------------------------------------------------------------- #
# system/blockMeshDict
# --------------------------------------------------------------------------- #
block_mesh_dict = """/*--------------------------------*- C++ -*----------------------------------*\\
| =========                 |                                                 |
| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |
|  \\\\    /   O peration     | Website:  www.openfoam.com                      |
|   \\\\  /    A nd           | Version:  10                                    |
|    \\\\/     M anipulation  |                                                 |
\\*---------------------------------------------------------------------------*/
FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      blockMeshDict;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

convertToMeters 1;

vertices
(
    (0 0 0)
    (9 0 0)
    (9 1 0)
    (0 1 0)
    (0 0 2)
    (9 0 2)
    (9 1 2)
    (0 1 2)
);

blocks
(
    hex (0 1 2 3 4 5 6 7) (45 10 20) simpleGrading (1 1 1)
);

edges
(
);

boundary
(
    hotWall
    {
        type wall;
        faces
        (
            (0 1 5 4)
        );
    }
    coldWall
    {
        type wall;
        faces
        (
            (3 2 6 7)
        );
    }
    sideWalls
    {
        type wall;
        faces
        (
            (0 4 7 3)
            (1 2 6 5)
            (0 3 2 1)
            (4 5 6 7)
        );
    }
);

mergeTypePoints none;
"""

